import{_ as a,c as e,o,a2 as r}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse('{"title":"布局概览 (Layouts Overview) - Rive 编辑器","description":"布局 (Layouts) 布局 (Layouts) 让你能够在 Rive 中构建响应式 UI 组件。你可以根据可用空间让设计适应 (Fit)、填充 (Fill) 或重排 (Reflow) 内容。","frontmatter":{"title":"布局概览 (Layouts Overview) - Rive 编辑器","description":"布局 (Layouts) 布局 (Layouts) 让你能够在 Rive 中构建响应式 UI 组件。你可以根据可用空间让设计适应 (Fit)、填充 (Fill) 或重排 (Reflow) 内容。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, 布局概览"}]]},"headers":[],"relativePath":"editor/layouts/overview.md","filePath":"editor/layouts/overview.md","lastUpdated":1774838907000}'),i={name:"editor/layouts/overview.md"};function l(s,t,n,u,d,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<p>布局 (Layouts)</p><h1 id="布局概览-layouts-overview" tabindex="-1">布局概览 (Layouts Overview) <a class="header-anchor" href="#布局概览-layouts-overview" aria-label="Permalink to &quot;布局概览 (Layouts Overview)&quot;">​</a></h1><p>布局 (Layouts) 让你能够在 Rive 中构建响应式 UI 组件。你可以根据可用空间让设计适应 (Fit)、填充 (Fill) 或重排 (Reflow) 内容。</p><h2 id="​-为什么使用布局" tabindex="-1"><a href="#why-use-layouts">​</a> 为什么使用布局？ <a class="header-anchor" href="#​-为什么使用布局" aria-label="Permalink to &quot;[​](#why-use-layouts) 为什么使用布局？&quot;">​</a></h2><p>传统的固定尺寸设计在不同屏幕或容器大小下可能会出现问题。通过布局，你可以创建：</p><ul><li>能够自适应窗口大小的<strong>响应式界面</strong>。</li><li>当内容变化时（如文本长度改变）<strong>自动调整</strong>的组件。</li><li>类似 Web 开发中 Flexbox 的<strong>流式排版</strong>效果。</li></ul><h2 id="​-布局类型" tabindex="-1"><a href="#layout-types">​</a> 布局类型 <a class="header-anchor" href="#​-布局类型" aria-label="Permalink to &quot;[​](#layout-types) 布局类型&quot;">​</a></h2><p>布局容器有几种类型，主要决定了子元素的排列方向：</p><ul><li><strong>Row (行)</strong>：子元素水平排列。</li><li><strong>Column (列)</strong>：子元素垂直排列。</li><li><strong>Stack (堆叠)</strong>：子元素在同一位置叠加（类似绝对定位）。</li></ul><h2 id="​-快速开始" tabindex="-1"><a href="#getting-started">​</a> 快速开始 <a class="header-anchor" href="#​-快速开始" aria-label="Permalink to &quot;[​](#getting-started) 快速开始&quot;">​</a></h2><ol><li>选中你想要放入布局的对象。</li><li>在检查器 (Inspector) 中点击 <strong>Layout</strong> 按钮，将其转换为布局容器。</li><li>调整布局属性，如<strong>方向 (Direction)</strong>、<strong>间距 (Gap)</strong>、<strong>对齐 (Alignment)</strong> 等。</li></ol><p>布局可以嵌套（布局内含布局），以创建复杂的响应式结构。</p><h2 id="​-核心概念" tabindex="-1"><a href="#key-concepts">​</a> 核心概念 <a class="header-anchor" href="#​-核心概念" aria-label="Permalink to &quot;[​](#key-concepts) 核心概念&quot;">​</a></h2><ul><li><strong>Fit 内容 (Hug)</strong>：布局容器的尺寸收缩以包裹其子元素。</li><li><strong>Fill 空间</strong>：子元素扩展以填满布局容器的可用空间。</li><li><strong>Reflow 重排</strong>：当容器尺寸改变时，子元素自动重新定位。</li></ul><h2 id="​-高级特性" tabindex="-1"><a href="#advanced-features">​</a> 高级特性 <a class="header-anchor" href="#​-高级特性" aria-label="Permalink to &quot;[​](#advanced-features) 高级特性&quot;">​</a></h2><p>布局还支持：</p><ul><li><strong><a href="/docs/editor/layouts/n-slicing">N轴切片 (N-Slicing)</a></strong>：让位图或矢量设计可伸缩而不失真。</li><li><strong><a href="/docs/editor/layouts/scrolling">滚动 (Scrolling)</a></strong>：为溢出内容提供触摸滚动功能。</li><li><strong><a href="/docs/editor/layouts/layout-animation">布局动画 (Animation)</a></strong>：定义内容重排时的过渡插值。</li></ul><p><a href="/docs/editor/layouts/n-slicing">N轴切片 (N-Slicing)</a><a href="/docs/editor/layouts/layout-parameters">布局参数 (Parameters)</a></p>',18)])])}const p=a(i,[["render",l]]);export{h as __pageData,p as default};
